set-variable.value:
@{
      try {
        var raw = context.Request.Body.As<string>(preserveContent: true);
        if (System.Text.Encoding.UTF8.GetByteCount(raw) > 65536) { return "Request exceeds 64 KiB"; }
        var body = Newtonsoft.Json.Linq.JObject.Parse(raw);
        if (body["input"] == null || (body["input"].Type != Newtonsoft.Json.Linq.JTokenType.String && body["input"].Type != Newtonsoft.Json.Linq.JTokenType.Array)) { return "input must be text or a Responses input list"; }
        if (body["stream"] != null && body["stream"].Type != Newtonsoft.Json.Linq.JTokenType.Boolean) { return "stream must be boolean"; }
        if (body["urls_csv"] != null || body["blocked_domains"] != null) { return "Use tools[].filters.blocked_domains"; }
        if (body["background"] != null && (body["background"].Type != Newtonsoft.Json.Linq.JTokenType.Boolean || (bool)body["background"])) { return "background requests are not supported"; }
        if (body["previous_response_id"] != null || body["conversation"] != null) { return "Use stateless input; conversation and previous_response_id are not supported"; }
        if (body["tools"] != null) {
          var tools = body["tools"] as Newtonsoft.Json.Linq.JArray;
          if (tools == null) { return "tools must be an array"; }
          foreach (var tool in tools) {
            if (!(tool is Newtonsoft.Json.Linq.JObject) || (string)tool["type"] != "web_search") { return "This lab supports only the hosted web_search tool"; }
            var filters = tool["filters"];
            if (filters != null && filters.Type != Newtonsoft.Json.Linq.JTokenType.Null) {
              if (!(filters is Newtonsoft.Json.Linq.JObject)) { return "web_search.filters must be an object or null"; }
              var blocked = filters["blocked_domains"];
              if (blocked != null && blocked.Type != Newtonsoft.Json.Linq.JTokenType.Null) {
                if (!(blocked is Newtonsoft.Json.Linq.JArray) || blocked.Count() > 100) { return "blocked_domains must be an array of at most 100 hostnames"; }
                foreach (var domain in blocked) {
                  if (domain.Type != Newtonsoft.Json.Linq.JTokenType.String || !System.Text.RegularExpressions.Regex.IsMatch((string)domain, @"^(?=.{1,253}\.?$)(?:[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?\.)+[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?\.?$")) { return "blocked_domains must contain DNS hostnames; use punycode for internationalized names"; }
                }
              }
            }
          }
        }
        if (body["max_output_tokens"] != null && (body["max_output_tokens"].Type != Newtonsoft.Json.Linq.JTokenType.Integer || (int)body["max_output_tokens"] < 16 || (int)body["max_output_tokens"] > 4096)) { return "max_output_tokens must be between 16 and 4096"; }
        return "";
      } catch { return "Invalid JSON request"; }
    }

@{
      var body = Newtonsoft.Json.Linq.JObject.Parse((string)context.Variables["originalRequest"]);
      var tools = body["tools"] as Newtonsoft.Json.Linq.JArray;
      return tools != null && tools.Count > 0;
    }

@{
      var body = Newtonsoft.Json.Linq.JObject.Parse((string)context.Variables["originalRequest"]);
      var tools = body["tools"] as Newtonsoft.Json.Linq.JArray;
      var required = Newtonsoft.Json.Linq.JArray.Parse((string)context.Variables["requiredDomains"]);
      if (tools != null) {
        foreach (var tool in tools) {
          var filters = tool["filters"] as Newtonsoft.Json.Linq.JObject;
          if (filters == null) { filters = new Newtonsoft.Json.Linq.JObject(); tool["filters"] = filters; }
          var blocked = filters["blocked_domains"] as Newtonsoft.Json.Linq.JArray ?? new Newtonsoft.Json.Linq.JArray();
          var merged = new Newtonsoft.Json.Linq.JArray();
          foreach (var domain in blocked.Concat(required)) {
            var host = ((string)domain).ToLowerInvariant().TrimEnd('.');
            if (!merged.Any(existing => (string)existing == host)) { merged.Add(host); }
          }
          filters["blocked_domains"] = merged;
        }
      }
      body["model"] = "{deployment}";
      body["store"] = false;
      if (body["max_output_tokens"] == null) { body["max_output_tokens"] = 4096; }
      return body.ToString(Newtonsoft.Json.Formatting.None);
    }

@{
      var domains = Newtonsoft.Json.Linq.JArray.Parse((string)context.Variables["requiredDomains"]);
      var body = Newtonsoft.Json.Linq.JObject.Parse((string)context.Variables["upstreamRequest"]);
      var tools = body["tools"] as Newtonsoft.Json.Linq.JArray;
      if (tools != null) {
        foreach (var tool in tools) {
          foreach (var domain in (Newtonsoft.Json.Linq.JArray)tool["filters"]["blocked_domains"]) {
            if (!domains.Any(existing => string.Equals((string)existing, (string)domain, StringComparison.OrdinalIgnoreCase))) { domains.Add(domain.DeepClone()); }
          }
        }
      }
      return domains.ToString(Newtonsoft.Json.Formatting.None);
    }

@{
          try {
            var raw = (string)context.Variables["initialBody"];
            var contentType = ((IResponse)context.Variables["initial"]).Headers.GetValueOrDefault("Content-Type", "");
            if (!contentType.StartsWith("application/json", StringComparison.OrdinalIgnoreCase)) { return ""; }
            return Newtonsoft.Json.Linq.JObject.Parse(raw).ToString(Newtonsoft.Json.Formatting.None);
          } catch { return ""; }
        }

@{
          var response = Newtonsoft.Json.Linq.JObject.Parse((string)context.Variables["initialResponse"]);
          var metrics = new Newtonsoft.Json.Linq.JObject();
          var count = response.SelectToken("tool_usage.web_search.num_requests");
          var tokens = response.SelectToken("usage.total_tokens");
          metrics["web_search_count"] = count != null && count.Type == Newtonsoft.Json.Linq.JTokenType.Integer && (decimal)count >= 0 && (decimal)count <= 1000000000000000000m ? count.DeepClone() : Newtonsoft.Json.Linq.JValue.CreateNull();
          metrics["total_tokens"] = tokens != null && tokens.Type == Newtonsoft.Json.Linq.JTokenType.Integer && (decimal)tokens >= 0 && (decimal)tokens <= 1000000000000000000m ? tokens.DeepClone() : Newtonsoft.Json.Linq.JValue.CreateNull();
          return metrics.ToString(Newtonsoft.Json.Formatting.None);
        }

@{
          var response = Newtonsoft.Json.Linq.JObject.Parse((string)context.Variables["initialResponse"]);
          var output = response["output"] as Newtonsoft.Json.Linq.JArray;
          if (output == null) { return false; }
          foreach (var item in output) {
            if (item is Newtonsoft.Json.Linq.JObject && (string)item["type"] == "web_search_call") { return true; }
          }
          return false;
        }

set-header.value:
@{
                var metrics = Newtonsoft.Json.Linq.JObject.Parse((string)context.Variables["initialMetrics"]);
                var known = metrics.Properties().Count(p => p.Value.Type != Newtonsoft.Json.Linq.JTokenType.Null);
                return known == 2 ? "reported" : known == 1 ? "partial" : "unavailable";
              }

when.set-body:
@{
          var original = Newtonsoft.Json.Linq.JObject.Parse((string)context.Variables["originalRequest"]);
          return new Newtonsoft.Json.Linq.JObject(
            new Newtonsoft.Json.Linq.JProperty("response", Newtonsoft.Json.Linq.JObject.Parse((string)context.Variables["initialResponse"])),
            new Newtonsoft.Json.Linq.JProperty("blocked_domains", Newtonsoft.Json.Linq.JArray.Parse((string)context.Variables["effectiveDomains"])),
            new Newtonsoft.Json.Linq.JProperty("stream", (bool?)original["stream"] ?? false)
          ).ToString(Newtonsoft.Json.Formatting.None);
        }
